output = []
for r in range(len(input_grid)):
    new_row = [5] * len(input_grid[0])

    for c in range(len(input_grid[0])):
        if input_grid[r][c] == 5:
            continue

        color = input_grid[r][c]
        # Find component containing this cell
        comp_key = tuple(sorted(find_connected_components_by_color(r, c)))
        if len(comp_key) >= 3:
            new_row[c] = color

    output.append(new_row)

print("Size filter guess:")
for i, row in enumerate(output[:4]):
    print(f"Row {i}: {row}")

# Hypothesis 2b: Keep only components size >= 3, use 0 as background
output = []
for r in range(len(input_grid)):
    new_row = [0] * len(input_grid[0])  # Default to 0

    for c in range(len(input_grid[0])):
        if input_grid[r][c] == 5:
            continue

        color = input_grid[r][c]
        comp = find_connected_components_by_color(r, c)
        if len(comp) >= 3:
            new_row[c] = color

    output.append(new_row)

print("Large component filter with 0 background:")
for row in output[:4]:
    print(row)

# Hypothesis: Keep only components of size >= 4 (very large), everything else becomes 0
output = []
for r in range(len(input_grid)):
    new_row = [0] * len(input_grid[0])

    for c in range(len(input_grid[0])):
        if input_grid[r][c] == 5:
            continue

        color = input_grid[r][c]
        comp = find_connected_components_by_color(r, c)
        # Use set to dedupe
        unique_cells = set()
        for rr, cc in comp:
            unique_cells.add((rr, cc))

        if len(unique_cells) >= 4:
            new_row[c] = color

    output.append(new_row)

print("Size >= 4 filter:")
for row in output[:6]:
    print(row)

# Find all components with their sizes and pick the largest one
all_comps = {}
for r in range(len(input_grid)):
    for c in range(len(input_grid[0])):
        if input_grid[r][c] != 5:
            comp = find_comp_cells(r, c)
            key = tuple(sorted(comp))
            if key not in all_comps:
                all_comps[key] = {'color': input_grid[r][c], 'cells': set()}
            all_comps[key]['cells'].update(comp)

# Find largest component by cell count
largest = None
largest_size = 0
for key, info in all_comps.items():
    size = len(info['cells'])
    if size > largest_size:
        largest = info
        largest_size = size

print("Largest component:", largest, "size:", largest_size)

# Output: keep only largest component, everything else becomes 0
output = []
for r in range(len(input_grid)):
    new_row = [0] * len(input_grid[0])
    for c in range(len(input_grid[0])):
        if (r, c) in largest['cells']:
            new_row[c] = largest['color']
    output.append(new_row)

print("Keep only largest:")
for row in output[:5]:
    print(row)

